// src/pages/mainboard/MainBoardPage.jsx

import React, { useState } from 'react';
import { startWatcher, stopWatcher } from '../../api/WatcherApi';

function MainBoardPage() {

  // TODO: 나중에 이 값들은 백엔드/상태에서 가져오도록 변경
  const [protectionStatus] = useState('안전');
  const [lastScan] = useState('2시간 전');
  const [scanProgress, setScanProgress] = useState(0);

  // 🔹 감시 대상 폴더: 처음에는 비어 있음
  const [folders, setFolders] = useState([]);

  // 🔹 임시 더미 최근 이벤트 (나중에 백엔드 연동)
  const [recentEvents] = useState([
    {
      id: 1,
      title: '의심스러운 파일 변경 감지',
      path: '/Users/.../문서/report.pdf',
      time: '1시간 전',
      level: 'warning',
    },
    {
      id: 2,
      title: '대량 파일 수정 감지',
      path: '/Users/.../사진',
      time: '2시간 전',
      level: 'danger',
    },
  ]);

  const [isScanning, setIsScanning] = useState(false);

  // ================== 검사 시작 ==================
  const handleScanNow = async () => {
    try {
      const target = folders[0]; // 일단 첫 번째 폴더를 대상으로 사용

      if (!target) {
        alert('감시할 폴더가 없습니다.\n먼저 "폴더 추가"에서 경로를 등록해주세요.');
        return;
      }

      if (!target.path) {
        alert('폴더 경로 정보가 없습니다.');
        return;
      }

      setIsScanning(true);
      setScanProgress(5); // UI용 임시값

      // 🔥 사용자가 입력한 실제 경로를 그대로 백엔드로 전달
      const result = await startWatcher(target.path);
      console.log('startWatcher result:', result);

      // TODO: 백엔드 응답에 따라 진행률/상태 갱신
      setScanProgress(30);
    } catch (e) {
      console.error(e);
      alert('검사 시작 중 오류가 발생했습니다.\n' + e.message);
    } finally {
      setIsScanning(false);
    }
  };

  // ================== 검사 중지 ==================
  const handlePause = async () => {
    try {
      const result = await stopWatcher();
      console.log('stopWatcher result:', result);
      // TODO: 진행률/상태 갱신
    } catch (e) {
      console.error(e);
      alert('검사 중지 중 오류가 발생했습니다.\n' + e.message);
    }
  };

  // ================== 폴더 추가/삭제 ==================

  // 사용자가 직접 경로 문자열을 입력해서 설정
  const handleAddFolder = () => {
    const path = window.prompt(
      '감시할 폴더의 전체 경로를 입력하세요.\n예: /Users/sanghyeok/Desktop/testwatch'
    );
    if (!path) return;

    // 마지막 디렉토리 이름을 name 으로 사용
    const segments = path.split(/[\\/]/).filter(Boolean);
    const name = segments[segments.length - 1] || path;

    setFolders((prev) => [
      ...prev,
      {
        id: prev.length === 0 ? 1 : Math.max(...prev.map((f) => f.id)) + 1,
        name,
        path, // 🔥 임시가 아니라, 사용자가 입력한 실제 경로
      },
    ]);
  };

  const handleRemoveFolder = (id) => {
    setFolders((prev) => prev.filter((f) => f.id !== id));
  };

  // ================== 렌더 ==================

  return (
    <div className="mainboard-root">
      {/* 보호 상태 배너 */}
      <div className="status-banner">
        <div className="status-left">
          <div className="status-dot status-dot-green" />
          <div className="status-text">
            현재 보호 상태:
            <span className="status-text-strong">{protectionStatus}</span>
          </div>
        </div>
        <div className="status-right">
          마지막 검사: <span>{lastScan}</span>
        </div>
      </div>

      {/* 메인 그리드 */}
      <div className="mainboard-grid">
        {/* 좌측: 검사 컨트롤 + 폴더 리스트 */}
        <section className="main-left">
          {/* 검사 컨트롤 */}
          <div className="scan-panel">
            <div className="scan-buttons">
              <button
                className="btn btn-primary"
                onClick={handleScanNow}
                disabled={isScanning}
              >
                {isScanning ? '검사 중...' : '지금 검사'}
              </button>

              <button className="btn" onClick={handlePause}>
                일시 중지
              </button>
            </div>

            <div className="scan-progress">
              <div className="scan-progress-bar">
                <div
                  className="scan-progress-fill"
                  style={{ width: `${scanProgress}%` }}
                />
              </div>
              <div className="scan-progress-text">
                진행률: {scanProgress}%
              </div>
            </div>
          </div>

          {/* 폴더 리스트 */}
          <div className="folder-panel">
            <div className="panel-header">
              <h2>감시 대상 폴더</h2>
            </div>
            <div className="folder-list">
              {folders.map((f) => (
                <div key={f.id} className="folder-item">
                  <div className="folder-name">
                    {f.name}
                    <div
                      style={{
                        fontSize: '11px',
                        color: '#9ca3af',
                        marginTop: '2px',
                      }}
                    >
                      {f.path}
                    </div>
                  </div>
                  <button
                    className="btn-icon"
                    onClick={() => handleRemoveFolder(f.id)}
                  >
                    삭제
                  </button>
                </div>
              ))}
            </div>
            <button className="btn btn-outline" onClick={handleAddFolder}>
              폴더 추가
            </button>
          </div>
        </section>

        {/* 우측: 최근 이벤트 */}
        <section className="main-right">
          <div className="panel-header">
            <h2>최근 이벤트</h2>
          </div>
          <div className="event-list">
            {recentEvents.length === 0 && (
              <div className="event-empty">최근 이벤트가 없습니다.</div>
            )}
            {recentEvents.map((ev) => (
              <div key={ev.id} className="event-card">
                <div className="event-title">{ev.title}</div>
                <div className="event-path">{ev.path}</div>
                <div className="event-meta">
                  <span className="event-time">{ev.time}</span>
                  <span
                    className={
                      'event-level ' +
                      (ev.level === 'danger'
                        ? 'event-level-danger'
                        : 'event-level-warning')
                    }
                  >
                    {ev.level === 'danger' ? '위험' : '주의'}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
}

export default MainBoardPage;
